-- Source: database/functions/eshop_forms/admin_form_orders.sql
-- Administrative entrypoints delegate the same checkout and single receipt as
-- public/UI creation. No ticket/payment shadow writer or second intent exists.
CREATE OR REPLACE FUNCTION public.check_form_order_scope_internal(p_occasion bigint,p_organization bigint,p_unit bigint,p_form bigint,p_write boolean DEFAULT true)
RETURNS void LANGUAGE plpgsql SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.check_operator_order_scope_internal_v1(p_occasion,p_organization,p_unit,p_write);
 IF NOT EXISTS(SELECT 1 FROM public.forms WHERE id=p_form AND occasion=p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='foreign order form'; END IF;
END $$;
CREATE OR REPLACE FUNCTION public.form_order_input_internal(p_form bigint,p_input jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public,extensions AS $$
BEGIN
 IF jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>1048576
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_input) k WHERE k NOT IN ('email','fields','ticket','lang','form','payment_method'))
  OR jsonb_typeof(p_input->'ticket') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'ticket') NOT BETWEEN 1 AND 1000
  OR nullif(p_input->>'email','') IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='invalid administrative order'; END IF;
 IF p_input ? 'form' AND p_input->>'form' IS DISTINCT FROM (SELECT key::text FROM public.forms WHERE id=p_form) THEN
  RAISE insufficient_privilege USING MESSAGE='foreign order form key'; END IF;
 IF p_input ? 'payment_method' AND p_input->>'payment_method' IS DISTINCT FROM 'bank' THEN
  RAISE invalid_parameter_value USING MESSAGE='administrative card payment unsupported'; END IF;
 RETURN p_input||jsonb_build_object('form',(SELECT key FROM public.forms WHERE id=p_form),'payment_method','bank');
END $$;
CREATE OR REPLACE FUNCTION public.form_order_quote_internal(p_order bigint)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 SELECT jsonb_build_object('newOrder',jsonb_build_object('amount',o.price::text,'currencyCode',o.currency_code,
  'state',o.state,'paymentMethod',p.payment_method,'bankAccountId',p.bank_account,
  'bankAccountNumber',ba.account_number,'bankAccountDisplay',ba.account_number_human_readable,
  'ticketCount',(SELECT count(DISTINCT ticket) FROM eshop.order_product_ticket WHERE "order"=o.id)))
 FROM eshop.orders o LEFT JOIN eshop.payment_info p ON p.id=o.payment_info LEFT JOIN eshop.bank_accounts ba ON ba.id=p.bank_account WHERE o.id=p_order;
$$;
CREATE OR REPLACE FUNCTION public.form_order_facts_internal(p_form bigint)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 SELECT jsonb_build_object('form',(SELECT to_jsonb(f)-ARRAY['key','link','created_at'] FROM public.forms f WHERE id=p_form),
  'fields',snap->'fields','products',snap->'products','productTypes',snap->'productTypes')
 FROM (SELECT public.get_form_authoring_snapshot_internal(p_form) snap) s;
$$;
CREATE OR REPLACE FUNCTION public.preview_form_order_internal(p_form bigint,p_input jsonb)
RETURNS jsonb LANGUAGE plpgsql SET search_path=public,extensions AS $$
DECLARE result jsonb; quote jsonb; facts jsonb; snap jsonb;
BEGIN
 facts:=public.form_order_facts_internal(p_form);
 BEGIN
  result:=public.create_ticket_order_command_internal(public.form_order_input_internal(p_form,p_input),extensions.gen_random_uuid(),extensions.gen_random_uuid(),NULL);
  IF (result->>'code')::int=200 THEN quote:=public.form_order_quote_internal((result#>>'{data,order,id}')::bigint); END IF;
  RAISE SQLSTATE 'P0F90' USING MESSAGE='rollback administrative order quote';
 EXCEPTION WHEN SQLSTATE 'P0F90' THEN NULL; END;
 IF (result->>'code')::int<>200 THEN RETURN jsonb_build_object('code',422,'reason','ORDER_NOT_CREATABLE'); END IF;
 RETURN jsonb_build_object('code',200,'quote',quote,'confirmationHash',encode(extensions.digest(
  jsonb_build_object('actor',auth.uid(),'form',p_form,'input',p_input,'facts',facts,'quote',quote)::text,'sha256'),'hex'));
END $$;
CREATE OR REPLACE FUNCTION public.lock_form_order_internal(p_occasion bigint,p_form bigint)
RETURNS void LANGUAGE plpgsql SET search_path=public,extensions AS $$
BEGIN
 -- Same parent order as actual checkout and the administration seat flow.
 PERFORM public.lock_blueprint_scope_internal(ARRAY[p_occasion]);
 PERFORM 1 FROM public.forms WHERE id=p_form FOR UPDATE;
 PERFORM 1 FROM eshop.product_types WHERE id IN(SELECT product_type FROM public.form_fields WHERE form=p_form) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.products WHERE product_type IN(SELECT product_type FROM public.form_fields WHERE form=p_form) ORDER BY id FOR UPDATE;
END $$;
CREATE OR REPLACE FUNCTION public.preview_admin_form_order(p_occasion bigint,p_organization bigint,p_unit bigint,p_form bigint,p_input jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.check_form_order_scope_internal(p_occasion,p_organization,p_unit,p_form);
 PERFORM public.lock_form_order_internal(p_occasion,p_form);
 RETURN public.preview_form_order_internal(p_form,p_input)||jsonb_build_object('occasionId',p_occasion,'formId',p_form,'actorId',auth.uid());
END $$;
CREATE OR REPLACE FUNCTION public.create_admin_form_order(p_occasion bigint,p_organization bigint,p_unit bigint,p_form bigint,p_input jsonb,
 p_confirmation_hash text,p_expected_actor uuid,p_command_id uuid,p_client_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE prior jsonb; receipt_status text; preview jsonb; quote jsonb; result jsonb; context jsonb;
BEGIN
 IF p_expected_actor IS DISTINCT FROM auth.uid() OR auth.uid() IS NULL OR p_confirmation_hash IS NULL OR p_confirmation_hash !~ '^[a-f0-9]{64}$' THEN
  RAISE insufficient_privilege USING MESSAGE='confirmed order actor required'; END IF;
 PERFORM public.check_form_order_scope_internal(p_occasion,p_organization,p_unit,p_form);
 PERFORM public.lock_form_order_internal(p_occasion,p_form);
 SELECT response,status INTO prior,receipt_status FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=auth.uid()
  AND occasion=p_occasion AND command_name='inventory.order.create';
 IF receipt_status='expired' THEN RETURN jsonb_build_object('code',410,'errorCode','COMMAND_EXPIRED_DO_NOT_REPLAY'); END IF;
 IF prior IS NOT NULL THEN quote:=prior#>'{data,adminQuote}';
 ELSE
  preview:=public.preview_form_order_internal(p_form,p_input);
  IF preview->>'confirmationHash' IS DISTINCT FROM p_confirmation_hash THEN
   RETURN jsonb_build_object('code',409,'errorCode','ORDER_CHANGED_REPREVIEW_REQUIRED'); END IF;
  quote:=preview->'quote';
 END IF;
 context:=jsonb_build_object('occasion',p_occasion,'organization',p_organization,'unit',p_unit,'form',p_form,
  'actor',auth.uid(),'confirmationHash',p_confirmation_hash,'quote',quote);
 result:=public.create_ticket_order_command_internal(public.form_order_input_internal(p_form,p_input),p_command_id,p_client_id,context);
 IF prior IS NULL AND (result->>'code')::int=200 AND
   public.form_order_quote_internal((result#>>'{data,order,id}')::bigint) IS DISTINCT FROM quote THEN
  RAISE serialization_failure USING MESSAGE='order quote changed during creation'; END IF;
 PERFORM public.check_form_order_scope_internal(p_occasion,p_organization,p_unit,p_form);
 RETURN result||jsonb_build_object('data',(result->'data')||jsonb_build_object('quote',result#>'{data,adminQuote}',
  'adminScope',jsonb_build_object('occasionId',p_occasion,'formId',p_form,'actorId',auth.uid())));
END $$;
REVOKE ALL ON FUNCTION public.check_form_order_scope_internal(bigint,bigint,bigint,bigint,boolean),
 public.form_order_input_internal(bigint,jsonb),public.form_order_quote_internal(bigint),public.preview_form_order_internal(bigint,jsonb),
 public.form_order_facts_internal(bigint),public.lock_form_order_internal(bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.preview_admin_form_order(bigint,bigint,bigint,bigint,jsonb),
 public.create_admin_form_order(bigint,bigint,bigint,bigint,jsonb,text,uuid,uuid,uuid) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.preview_admin_form_order(bigint,bigint,bigint,bigint,jsonb),
 public.create_admin_form_order(bigint,bigint,bigint,bigint,jsonb,text,uuid,uuid,uuid) TO authenticated;


-- Source: database/functions/eshop_waitlist/commands.sql
-- Edge is the trusted preparation boundary for random capabilities and sealed email.
-- It verifies the bearer user; SQL still checks the explicit actor's occasion rights.
CREATE OR REPLACE FUNCTION public.sanitize_waitlist_history_internal(p_value jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 IF jsonb_typeof(p_value)='object' THEN
  SELECT coalesce(jsonb_object_agg(key,public.sanitize_waitlist_history_internal(value)),'{}') INTO result
  FROM jsonb_each(p_value) WHERE lower(key) NOT IN
   ('token','secret','password','offertoken','managetoken','capability','waitlistenvelope','sealed','tokenhash','stripepaymentsource');
  RETURN result;
 ELSIF jsonb_typeof(p_value)='array' THEN
  SELECT coalesce(jsonb_agg(public.sanitize_waitlist_history_internal(value) ORDER BY ordinal),'[]') INTO result
  FROM jsonb_array_elements(p_value) WITH ORDINALITY item(value,ordinal);
  RETURN result;
 END IF;
 RETURN p_value;
END $$;
CREATE OR REPLACE FUNCTION public.snapshot_waitlist_tickets_internal(p_order bigint)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public,extensions AS $$
 SELECT coalesce(jsonb_agg(public.sanitize_waitlist_history_internal(to_jsonb(p)||jsonb_build_object('answers',p.data,'lifecycle',public.get_effective_waitlist_ticket_lifecycle_internal(p.id))) ORDER BY created_at,id),'[]')
 FROM public.get_order_tickets_internal(p_order) p;
$$;
REVOKE ALL ON FUNCTION public.sanitize_waitlist_history_internal(jsonb),public.snapshot_waitlist_tickets_internal(bigint)
 FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.execute_waitlist_command_client_sync_v1(
 p_operation text,p_payload jsonb,p_command_id uuid,p_client_id uuid,p_actor uuid DEFAULT NULL,p_deliveries jsonb DEFAULT '[]')
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE fid bigint; occ bigint; oid bigint; offer uuid; mode text; c jsonb; result jsonb; claim jsonb;
 hash text; selected bigint[]; expected integer; changed integer; recipients jsonb; r jsonb; delivery jsonb;
 person jsonb; created_ticket bigint; slot_ids uuid[]; expiry timestamptz; f public.forms; people jsonb; n integer; before_users uuid[];
 previous_sub text; actor_kind text; o eshop.orders; entity_changes jsonb:='[]';
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_operation NOT IN ('register','send','accept','decline','cancel','withdraw') OR p_command_id IS NULL OR p_client_id IS NULL
 OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>4194304 THEN RAISE EXCEPTION 'Invalid waitlist command'; END IF;
 IF p_operation='register' THEN SELECT id INTO fid FROM public.forms WHERE key=(p_payload->>'form')::uuid;
 ELSIF p_operation='send' THEN fid:=(p_payload->>'formId')::bigint;
 ELSIF p_operation='withdraw' THEN oid:=(p_payload->>'orderId')::bigint; SELECT form INTO fid FROM eshop.orders WHERE id=oid;
 ELSE offer:=(p_payload->>'offerId')::uuid; SELECT order_id,form_id INTO oid,fid FROM eshop.waitlist_offers WHERE id=offer; END IF;
 SELECT * INTO f FROM public.forms WHERE id=fid; occ:=f.occasion;
 PERFORM public.check_occasion_writable(occ);
 IF occ IS NULL THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 -- Match checkout and cancellation: scope precedes the form/order parents.
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 IF p_operation IN ('send','cancel') AND NOT public.can_write_orders_as_actor_internal(p_actor,occ) THEN
  RAISE insufficient_privilege USING MESSAGE='Order editor required'; END IF;
 previous_sub:=current_setting('request.jwt.claim.sub',true);
 PERFORM set_config('request.jwt.claim.sub',coalesce(p_actor::text,''),true);
 hash:=encode(extensions.digest(jsonb_build_object('operation',p_operation,'payload',p_payload#-'{orderDetails,stripePaymentSource}','actor',p_actor)::text,'sha256'),'hex');
 BEGIN
  IF p_actor IS NULL THEN claim:=public.begin_anonymous_client_mutation_v1(p_command_id,'inventory.waitlist.'||p_operation,occ,p_client_id,hash); actor_kind:='unknown';
  ELSE claim:=public.begin_client_mutation_v1(p_command_id,'inventory.waitlist.'||p_operation,occ,p_actor,hash); actor_kind:='user'; END IF;
 EXCEPTION WHEN invalid_parameter_value THEN
  PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true);
  RETURN jsonb_build_object('code',409,'errorCode','COMMAND_PAYLOAD_CONFLICT');
 END;
 IF claim->>'disposition'='replay' THEN
  PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true); RETURN public.project_local_payment_reference_order_internal(claim->'response'); END IF;
 SELECT coalesce(array_agg("user"),'{}') INTO before_users FROM public.occasion_users WHERE occasion=occ;
 BEGIN
  PERFORM 1 FROM public.forms WHERE id=fid FOR UPDATE;
 IF p_operation IN ('accept','decline','cancel','withdraw') THEN
  PERFORM public.check_waitlist_scope_internal(oid,offer,p_payload->>'token',p_actor,p_operation); END IF;

  PERFORM public.expire_waitlist_form_internal(fid);
  c:=public.get_form_capacity_snapshot_internal(fid);
  IF p_operation='register' THEN
   mode:=public.get_form_registration_mode_internal(fid);
   IF mode<>'waitlist' THEN RAISE EXCEPTION 'WAITLIST_NOT_AVAILABLE'; END IF;
   people:=public.normalize_form_ticket_answers_internal(fid,p_payload->'tickets');
   PERFORM public.validate_waitlist_answers_internal(fid,p_payload,people,true);
   IF nullif(p_payload->>'email','') IS NULL THEN RAISE EXCEPTION 'Email required'; END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(people) p CROSS JOIN LATERAL jsonb_array_elements(coalesce(p->'fields','[]')) a WHERE a ? 'product_type') THEN
    RAISE EXCEPTION 'Waitlist does not accept products'; END IF;
   oid:=public.allocate_ticket_order_identity_internal(fid);
   UPDATE eshop.orders SET state='waitlisted',price=NULL,payment_info=NULL,data=p_payload-'tickets'-'token' WHERE id=oid;
   FOR person IN SELECT * FROM jsonb_array_elements(people) LOOP
    INSERT INTO eshop.tickets(occasion,state,ticket_symbol,data,waitlist_queue_at)
     VALUES(occ,'waitlisted',NULL,public.extract_ticket_answers_internal(fid,person),clock_timestamp()) RETURNING id INTO created_ticket;
    INSERT INTO eshop.order_product_ticket("order",ticket,product) VALUES(oid,created_ticket,NULL); END LOOP;
   result:=jsonb_build_object('code',200,'order',jsonb_build_object('id',oid,'order_symbol',(SELECT order_symbol FROM eshop.orders WHERE id=oid),'state','waitlisted','payment_info',NULL,'price',NULL),
    'waitlistSummary',public.get_waitlist_summary_internal(oid),'email',public.enqueue_waitlist_email_internal(oid,NULL,p_command_id,p_deliveries->0));
  ELSIF p_operation='send' THEN
   SELECT * INTO f FROM public.forms WHERE id=fid;
   IF NOT f.waitlist_enabled THEN RAISE EXCEPTION 'WAITLIST_NOT_AVAILABLE'; END IF;
   IF f.capacity_revision<>(p_payload->>'revision')::bigint THEN
    RAISE EXCEPTION '%',jsonb_build_object('code',409,'errorCode','OFFER_CHANGED','capacity',c)::text; END IF;
   expiry:=(p_payload->>'expiresAt')::timestamptz;
   IF expiry IS NULL OR expiry<=clock_timestamp() THEN RAISE EXCEPTION 'OFFER_EXPIRED'; END IF;
   recipients:=p_payload->'recipients';
   IF jsonb_typeof(recipients)<>'array' OR jsonb_array_length(recipients)<1 OR
    jsonb_array_length(recipients)<>(SELECT count(DISTINCT x->>'orderId') FROM jsonb_array_elements(recipients) x) THEN RAISE EXCEPTION 'Invalid recipients'; END IF;
   SELECT sum((x->>'count')::integer) INTO n FROM jsonb_array_elements(recipients) x;
   IF n>(c->>'offerablePlaces')::integer THEN RAISE EXCEPTION 'FORM_CAPACITY_EXCEEDED'; END IF;
   PERFORM 1 FROM eshop.orders WHERE id IN(SELECT (x->>'orderId')::bigint FROM jsonb_array_elements(recipients) x) ORDER BY id FOR UPDATE;
   result:=jsonb_build_object('code',200,'offers','[]'::jsonb);
   FOR r IN SELECT * FROM jsonb_array_elements(recipients) ORDER BY (value->>'orderId')::bigint LOOP
    oid:=(r->>'orderId')::bigint; n:=(r->>'count')::integer;
    IF n<1 OR NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=oid AND form=fid AND state='waitlisted') THEN RAISE EXCEPTION 'Invalid recipient scope'; END IF;
    SELECT array_agg(id) INTO selected FROM (SELECT p.id FROM eshop.tickets p WHERE p.state='waitlisted'
     AND EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x.ticket=p.id AND x."order"=oid)
     AND NOT EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots s WHERE ticket_id=p.id AND outcome='pending')
     ORDER BY waitlist_queue_at,created_at,id LIMIT n FOR UPDATE) tickets;
    IF coalesce(cardinality(selected),0)<>n THEN RAISE EXCEPTION 'OFFER_CHANGED'; END IF;
    INSERT INTO eshop.waitlist_offers(order_id,form_id,created_by,expires_at,revision) VALUES(oid,fid,p_actor,expiry,f.capacity_revision) RETURNING id INTO offer;
    INSERT INTO eshop.waitlist_offer_slots(offer_id,ticket_id,form_id) SELECT offer,id,fid FROM unnest(selected) id;
    SELECT x INTO delivery FROM jsonb_array_elements(p_deliveries) x WHERE (x->>'orderId')::bigint=oid;
    result:=jsonb_set(result,'{offers}',result->'offers'||jsonb_build_array(jsonb_build_object('orderId',oid,'offerId',offer,'count',n,'expiresAt',expiry,
     'email',public.enqueue_waitlist_email_internal(oid,offer,p_command_id,delivery))));
    INSERT INTO eshop.orders_history("order",state,data) VALUES(oid,'waitlisted',jsonb_build_object('action','offer_sent','offerId',offer,'count',n,'expiresAt',expiry));
    entity_changes:=entity_changes||jsonb_build_array(jsonb_build_object('entityType','order','entityId',oid,'operation','update','safeLabel','Waitlist offer','changedFields',jsonb_build_array('waitlistSummary')));
   END LOOP;
  ELSIF p_operation='accept' THEN
   result:=public.accept_waitlist_offer_internal(p_payload,p_command_id,p_actor);
   entity_changes:=entity_changes||jsonb_build_array(jsonb_build_object('entityType','order','entityId',result#>>'{order,id}','operation','update','safeLabel','Accepted order','changedFields',jsonb_build_array('state','tickets','products','allocations')));
  ELSE
   PERFORM public.lock_order_capacity_scope_internal(ARRAY[oid]);
   IF (SELECT state FROM eshop.orders WHERE id=oid)<>'waitlisted' THEN RAISE EXCEPTION 'OFFER_SLOT_ALREADY_RESOLVED'; END IF;
   SELECT array_agg(x::bigint) INTO selected FROM jsonb_array_elements_text(p_payload->'ticketIds') x; n:=coalesce(cardinality(selected),0);
   IF n<1 OR n<>(SELECT count(DISTINCT x) FROM unnest(selected) x) THEN RAISE EXCEPTION 'Invalid persons'; END IF;
   IF n<>(SELECT count(*) FROM public.get_order_tickets_internal(oid) WHERE id=ANY(selected) AND state='waitlisted') THEN
    RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
   IF p_operation IN ('decline','cancel') AND n<>(SELECT count(*) FROM eshop.waitlist_offer_slots WHERE offer_id=offer AND outcome='pending' AND ticket_id=ANY(selected)) THEN
    RAISE EXCEPTION 'OFFER_SLOT_ALREADY_RESOLVED'; END IF;
   UPDATE eshop.waitlist_offer_slots SET outcome=CASE WHEN p_operation='decline' THEN 'declined' ELSE 'cancelled' END,updated_at=clock_timestamp()
    WHERE ticket_id=ANY(selected) AND outcome='pending' AND (p_operation='withdraw' OR offer_id=offer);
   UPDATE eshop.tickets SET state=CASE WHEN p_operation='withdraw' THEN 'storno' ELSE state END,
    waitlist_queue_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=ANY(selected);
   UPDATE eshop.waitlist_capabilities cap SET revoked_at=clock_timestamp() WHERE cap.order_id=oid AND kind='offer' AND NOT EXISTS
    (SELECT 1 FROM eshop.waitlist_offer_slots WHERE offer_id=cap.offer_id AND outcome='pending');
   result:=jsonb_build_object('code',200,'orderId',oid,'waitlistSummary',public.get_waitlist_summary_internal(oid));
  END IF;
  UPDATE public.forms SET capacity_revision=capacity_revision+1 WHERE id=fid;
  IF p_operation<>'send' THEN
   -- Acceptance owns its richer before/after snapshot at the same transaction
   -- boundary; avoid a second action-only row hiding that record in the detail.
   IF p_operation<>'accept' THEN
    INSERT INTO eshop.orders_history("order",state,data) VALUES(oid,(SELECT state FROM eshop.orders WHERE id=oid),
     jsonb_build_object('action','waitlist_'||p_operation,'commandId',p_command_id,
     'ticketIds',CASE WHEN p_operation='register' THEN
       (SELECT jsonb_agg(id ORDER BY created_at,id) FROM public.get_order_tickets_internal(oid))
       ELSE to_jsonb(selected) END,
     'tickets',public.snapshot_waitlist_tickets_internal(oid)));
   END IF;
   entity_changes:=entity_changes||jsonb_build_array(jsonb_build_object('entityType','order','entityId',oid,'operation','update','safeLabel','Waitlist order','changedFields',jsonb_build_array('waitlistSummary','tickets')));
  END IF;
  IF p_operation='register' THEN
   PERFORM public.notification_center_order_internal(oid,'waitlist_registered','created',p_actor);
  ELSIF p_operation='accept' THEN
   PERFORM public.notification_center_order_internal((result#>>'{order,id}')::bigint,'offer_accepted',offer::text||':'||p_command_id,p_actor,
    jsonb_build_object('offerId',offer,'count',jsonb_array_length(p_payload->'ticketIds')));
  ELSIF p_operation='withdraw' THEN
   PERFORM public.notification_center_order_internal(oid,'order_cancelled','withdraw:'||p_command_id,p_actor,jsonb_build_object('count',n));
  ELSIF p_operation='decline' THEN
   PERFORM public.notification_center_order_internal(oid,'offer_declined',offer::text||':'||p_command_id,p_actor,jsonb_build_object('offerId',offer,'count',n));
  END IF;
  PERFORM public.notification_center_form_capacity_internal(fid,p_actor);
  result:=result||jsonb_build_object('capacity',public.get_form_capacity_snapshot_internal(fid));
 EXCEPTION WHEN OTHERS THEN
  result:=CASE WHEN left(SQLERRM,1)='{' THEN SQLERRM::jsonb ELSE jsonb_build_object('code',409,'errorCode',SQLERRM,'message',SQLERRM) END;
  result:=public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
   CASE WHEN (result->>'code')::integer BETWEEN 200 AND 599 THEN (result->>'code')::integer ELSE 409 END,result);
  PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true); RETURN result;
 END;
 entity_changes:=entity_changes||jsonb_build_array(jsonb_build_object('entityType','form','entityId',fid,'operation','update','safeLabel','Form capacity','changedFields',jsonb_build_array('capacity','registrationMode')));
 IF p_operation='accept' AND p_payload ? 'administrativeApproval' THEN
  result:=result||jsonb_build_object('adminQuote',p_payload#>'{administrativeApproval,quote}',
   'adminScope',p_payload#>'{administrativeApproval,scope}','paymentPreparationPolicy','leased_keep_pending'); END IF;
 result:=public.complete_profile_inventory_membership_mutation_v1(p_command_id,occ,'inventory.waitlist.'||p_operation,entity_changes,before_users,result,actor_kind);
 PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true);
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.execute_waitlist_command_client_sync_v1(text,jsonb,uuid,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.execute_waitlist_command_client_sync_v1(text,jsonb,uuid,uuid,uuid,jsonb) TO service_role;


-- Source: database/functions/eshop_forms/admin_waitlist_acceptance.sql
-- Service-only rollback preview, used by the same administrative Edge channel.
CREATE OR REPLACE FUNCTION public.preview_admin_waitlist_acceptance(p_administration jsonb,p_payload jsonb,p_actor uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE previous_sub text:=current_setting('request.jwt.claim.sub',true); occ bigint;fid bigint;
 facts jsonb;result jsonb;quote jsonb;offer uuid;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_actor IS NULL OR jsonb_typeof(p_payload)<>'object' OR p_payload ? 'token' OR octet_length(p_payload::text)>1048576 THEN
  RAISE insufficient_privilege USING MESSAGE='administrative acceptance actor required'; END IF;
 occ:=(p_administration->>'occasionId')::bigint;fid:=(p_administration->>'formId')::bigint;offer:=(p_payload->>'offerId')::uuid;
 PERFORM set_config('request.jwt.claim.sub',p_actor::text,true);
 PERFORM public.check_form_order_scope_internal(occ,(p_administration->>'organizationId')::bigint,(p_administration->>'unitId')::bigint,fid);
 PERFORM public.lock_form_order_internal(occ,fid);
 PERFORM public.get_form_waitlist_context(occ,(p_administration->>'organizationId')::bigint,(p_administration->>'unitId')::bigint,fid,'accept',p_payload);
 p_payload:=(p_payload-ARRAY['approvalHash','administrativeApproval'])||jsonb_build_object('orderDetails',public.form_order_input_internal(fid,p_payload->'orderDetails'));
 facts:=jsonb_build_object('form',public.form_order_facts_internal(fid),'offer',(SELECT to_jsonb(w) FROM eshop.waitlist_offers w WHERE id=offer),
  'slots',(SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM eshop.waitlist_offer_slots s WHERE s.offer_id=offer));
 BEGIN
  result:=public.execute_waitlist_command_client_sync_v1('accept',p_payload,extensions.gen_random_uuid(),extensions.gen_random_uuid(),p_actor,'[]');
  IF (result->>'code')::int=200 THEN quote:=public.form_order_quote_internal((result#>>'{data,order,id}')::bigint); END IF;
  RAISE SQLSTATE 'P0F91' USING MESSAGE='rollback waiting acceptance quote';
 EXCEPTION WHEN SQLSTATE 'P0F91' THEN NULL; END;
 PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true);
 IF (result->>'code')::int<>200 THEN RETURN jsonb_build_object('code',422,'reason','ORDER_NOT_CREATABLE','occasionId',occ,'formId',fid,'actorId',p_actor); END IF;
 RETURN jsonb_build_object('code',200,'quote',quote,'occasionId',occ,'formId',fid,'actorId',p_actor,'confirmationHash',
  encode(extensions.digest(jsonb_build_object('actor',p_actor,'scope',p_administration,'payload',p_payload,'facts',facts,'quote',quote)::text,'sha256'),'hex'));
EXCEPTION WHEN OTHERS THEN
 PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true);RAISE;
END $$;
REVOKE ALL ON FUNCTION public.preview_admin_waitlist_acceptance(jsonb,jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.preview_admin_waitlist_acceptance(jsonb,jsonb,uuid) TO service_role;


-- Source: database/functions/eshop_orders/replacement_invoice_preparation.sql
-- Confirmed seat replacements and administrative form orders share this owner.
-- Their order allocation is already committed. Provider
-- preparation retries keep the new allocation and fence invoice POST separately.
CREATE TABLE IF NOT EXISTS eshop.replacement_invoice_preparations(
 command_id uuid PRIMARY KEY,
 order_id bigint NOT NULL UNIQUE REFERENCES eshop.orders(id) ON DELETE CASCADE,
 state text NOT NULL CHECK(state IN('claimed','retryable','unknown','complete')),
 dispatch_started boolean NOT NULL DEFAULT false,
 lease_token uuid,
 lease_until timestamptz,
 attempts integer NOT NULL DEFAULT 0,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK((lease_token IS NULL)=(lease_until IS NULL))
);
ALTER TABLE eshop.replacement_invoice_preparations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE eshop.replacement_invoice_preparations FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.claim_replacement_invoice_preparation(p_order bigint,p_command uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE attempt eshop.replacement_invoice_preparations;receipt jsonb;token uuid:=extensions.gen_random_uuid();state text;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
 SELECT o.state INTO state FROM eshop.orders o WHERE o.id=p_order FOR UPDATE;
 SELECT r.response INTO receipt FROM public.client_mutation_receipts r
  WHERE r.command_id=p_command AND (r.command_name='inventory.order.replace' OR (r.command_name IN('inventory.order.create','inventory.waitlist.accept') AND r.response#>'{data,adminQuote}' IS NOT NULL)) AND r.status='completed'
  AND r.response->>'status'='applied' AND (r.response#>>'{data,order,id}')::bigint=p_order;
 IF receipt IS NULL AND NOT EXISTS(SELECT 1 FROM eshop.replacement_invoice_preparations a
  WHERE a.command_id=p_command AND a.order_id=p_order) THEN
  RAISE insufficient_privilege USING MESSAGE='replacement receipt unavailable'; END IF;
 IF state IN('ordered','paid') THEN RETURN jsonb_build_object('status','complete'); END IF;
 IF state IS DISTINCT FROM 'preparing_payment' THEN RETURN jsonb_build_object('status','closed'); END IF;
 PERFORM 1 FROM public.email_messages q WHERE q.code='TICKET_ORDER_CONFIRMATION'
  AND q.data->>'command_id'=p_command::text AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order
  AND q.data->>'fakturoid_pending'='true' FOR UPDATE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='invoice preparation claim unavailable'; END IF;
 SELECT * INTO attempt FROM eshop.replacement_invoice_preparations WHERE command_id=p_command FOR UPDATE;
 IF NOT FOUND THEN
  -- Legacy pending receipts may already have dispatched an invoice. They are
  -- lookup-only; absence in one GET is not proof that a POST never executed.
  INSERT INTO eshop.replacement_invoice_preparations(command_id,order_id,state,dispatch_started)
   VALUES(p_command,p_order,'retryable',receipt#>>'{data,paymentPreparationPolicy}' IS DISTINCT FROM 'leased_keep_pending');
  SELECT * INTO STRICT attempt FROM eshop.replacement_invoice_preparations WHERE command_id=p_command FOR UPDATE;
 END IF;
 IF attempt.order_id<>p_order THEN RAISE insufficient_privilege USING MESSAGE='invoice order mismatch'; END IF;
 IF attempt.state='complete' THEN RETURN jsonb_build_object('status','complete'); END IF;
 IF attempt.lease_until>clock_timestamp() THEN RETURN jsonb_build_object('status','busy'); END IF;
 UPDATE eshop.replacement_invoice_preparations SET state='claimed',lease_token=token,
  lease_until=clock_timestamp()+interval '180 seconds',attempts=attempts+1,updated_at=clock_timestamp()
 WHERE command_id=p_command;
 RETURN jsonb_build_object('status','claimed','token',token,'allowCreate',NOT attempt.dispatch_started);
END $$;
REVOKE ALL ON FUNCTION public.claim_replacement_invoice_preparation(bigint,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_replacement_invoice_preparation(bigint,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.mark_replacement_invoice_dispatch(p_order bigint,p_command uuid,p_token uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 UPDATE eshop.replacement_invoice_preparations SET dispatch_started=true,updated_at=clock_timestamp()
 WHERE command_id=p_command AND order_id=p_order AND lease_token=p_token AND lease_until>clock_timestamp()
  AND state='claimed' AND NOT dispatch_started;
 IF NOT FOUND THEN RAISE check_violation USING MESSAGE='invoice dispatch lease unavailable'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.mark_replacement_invoice_dispatch(bigint,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mark_replacement_invoice_dispatch(bigint,uuid,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.release_replacement_invoice_preparation(p_order bigint,p_command uuid,p_token uuid,p_not_created boolean DEFAULT false)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_not_created IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='invoice outcome required'; END IF;
 UPDATE eshop.replacement_invoice_preparations SET
  dispatch_started=dispatch_started AND NOT p_not_created,
  state=CASE WHEN dispatch_started AND NOT p_not_created THEN 'unknown' ELSE 'retryable' END,
  lease_token=NULL,lease_until=NULL,updated_at=clock_timestamp()
 WHERE command_id=p_command AND order_id=p_order AND lease_token=p_token AND state='claimed';
 RETURN FOUND;
END $$;
REVOKE ALL ON FUNCTION public.release_replacement_invoice_preparation(bigint,uuid,uuid,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.release_replacement_invoice_preparation(bigint,uuid,uuid,boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.complete_replacement_invoice_preparation(p_order bigint,p_command uuid,p_token uuid,p_variable_symbol bigint)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE symbol bigint;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
 PERFORM 1 FROM public.email_messages q WHERE q.code='TICKET_ORDER_CONFIRMATION'
  AND q.data->>'command_id'=p_command::text AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order FOR UPDATE;
 PERFORM 1 FROM eshop.replacement_invoice_preparations WHERE command_id=p_command AND order_id=p_order
  AND lease_token=p_token AND lease_until>clock_timestamp() AND state='claimed' FOR UPDATE;
 IF NOT FOUND THEN RAISE check_violation USING MESSAGE='invoice completion lease unavailable'; END IF;
 symbol:=public.complete_fakturoid_ticket_order_v1(p_order,p_command,p_variable_symbol);
 UPDATE eshop.replacement_invoice_preparations SET state='complete',lease_token=NULL,lease_until=NULL,updated_at=clock_timestamp()
 WHERE command_id=p_command AND order_id=p_order;
 RETURN symbol;
END $$;
REVOKE ALL ON FUNCTION public.complete_replacement_invoice_preparation(bigint,uuid,uuid,bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.complete_replacement_invoice_preparation(bigint,uuid,uuid,bigint) TO service_role;


-- Source: database/functions/eshop_waitlist/offers.sql
DROP FUNCTION IF EXISTS public.expire_waitlist_form_internal(bigint,timestamptz);
CREATE OR REPLACE FUNCTION public.expire_waitlist_form_internal(p_form bigint,p_at timestamptz DEFAULT clock_timestamp(),p_limit integer DEFAULT NULL)
RETURNS integer LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE n integer; nc_expired jsonb; nc_offer record;
BEGIN
 IF public.is_demo_occasion((SELECT occasion FROM public.forms WHERE id=p_form)) THEN RETURN 0; END IF;
 PERFORM 1 FROM public.forms WHERE id=p_form FOR UPDATE;
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO nc_expired FROM (
  SELECT w.id offer_id,w.order_id,w.expires_at,array_agg(s.id ORDER BY s.id) slots FROM
   (SELECT x.* FROM eshop.waitlist_offer_slots x JOIN eshop.waitlist_offers y ON y.id=x.offer_id
    WHERE y.form_id=p_form AND y.expires_at<=p_at AND x.outcome='pending' ORDER BY x.id LIMIT p_limit) s
   JOIN eshop.waitlist_offers w ON w.id=s.offer_id GROUP BY w.id,w.order_id,w.expires_at) x;
 WITH expired AS (UPDATE eshop.waitlist_offer_slots s SET outcome='expired',updated_at=p_at
 FROM eshop.waitlist_offers w WHERE w.id=s.offer_id AND w.form_id=p_form AND w.expires_at<=p_at AND s.outcome='pending'
 AND s.id IN(SELECT x.id FROM eshop.waitlist_offer_slots x JOIN eshop.waitlist_offers y ON y.id=x.offer_id WHERE y.form_id=p_form AND y.expires_at<=p_at AND x.outcome='pending' ORDER BY x.id LIMIT p_limit)
 RETURNING s.ticket_id)
 UPDATE eshop.tickets SET waitlist_queue_at=p_at,updated_at=p_at WHERE id IN(SELECT ticket_id FROM expired) AND state='waitlisted';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n>0 THEN
  UPDATE public.forms SET capacity_revision=capacity_revision+1 WHERE id=p_form;
  UPDATE eshop.waitlist_capabilities SET revoked_at=p_at WHERE form_id=p_form AND kind='offer' AND expires_at<=p_at AND revoked_at IS NULL;
 END IF;
 FOR nc_offer IN SELECT * FROM jsonb_to_recordset(nc_expired) AS r(offer_id uuid,order_id bigint,expires_at timestamptz,slots uuid[]) LOOP
  PERFORM public.notification_center_publish_internal((SELECT organization FROM public.occasions WHERE id=(SELECT occasion FROM public.forms WHERE id=p_form)),
   (SELECT occasion FROM public.forms WHERE id=p_form),'offer_expired','offer_expired:'||nc_offer.offer_id||':'||encode(extensions.digest(array_to_string(nc_offer.slots,','),'sha256'),'hex'),
   jsonb_build_object('orderId',nc_offer.order_id,'offerId',nc_offer.offer_id,'count',cardinality(nc_offer.slots)),NULL,nc_offer.expires_at);
 END LOOP;
 PERFORM public.notification_center_form_capacity_internal(p_form,NULL);
 RETURN n;
END $$;
CREATE OR REPLACE FUNCTION public.get_waitlist_offer_proposal_internal(p_form_id bigint,p_after bigint DEFAULT NULL,p_limit integer DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE f public.forms; c jsonb; proposals jsonb; available integer;
BEGIN
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form_id;
 PERFORM public.check_is_editor_order_on_occasion(f.occasion);
 PERFORM 1 FROM public.forms WHERE id=f.id FOR UPDATE;
 PERFORM public.expire_waitlist_form_internal(f.id);
 c:=public.get_form_capacity_snapshot_internal(f.id); available:=(c->>'offerablePlaces')::integer;
 -- count is the suggested allocation; waitingCount is the authoritative recipient limit.
 -- Keep unallocated eligible recipients so editors can adjust the allocation safely.
 WITH ranked AS (
  SELECT p.*,o.id order_id,row_number() OVER(ORDER BY p.waitlist_queue_at,p.created_at,p.id) position
  FROM eshop.tickets p
  JOIN LATERAL(SELECT DISTINCT x."order" FROM eshop.order_product_ticket x WHERE x.ticket=p.id) x ON true
  JOIN eshop.orders o ON o.id=x."order" WHERE o.form=f.id AND o.state='waitlisted'
   AND public.get_effective_waitlist_ticket_lifecycle_internal(p.id)='waiting'
 ), grouped AS (
  SELECT order_id,min(waitlist_queue_at) first_queue,count(*) total,count(*) FILTER(WHERE position<=available) offered
  FROM ranked GROUP BY order_id
 ), page AS (
  SELECT * FROM grouped WHERE p_after IS NULL OR order_id>p_after
  ORDER BY CASE WHEN p_limit IS NULL THEN first_queue END,order_id LIMIT p_limit
 )
 SELECT coalesce(jsonb_agg(jsonb_build_object('orderId',order_id,'count',offered,'waitingCount',total)
  ORDER BY CASE WHEN p_limit IS NULL THEN first_queue END,order_id),'[]') INTO proposals FROM page;
 RETURN jsonb_build_object('code',200,'formId',f.id,'revision',c->'revision','capacity',c,'recipients',proposals,
 'offerDurationSeconds',f.waitlist_offer_duration_seconds,'serverTime',clock_timestamp(),
 'nextCursor',CASE WHEN p_limit IS NOT NULL AND jsonb_array_length(proposals)=p_limit THEN (SELECT max((r->>'orderId')::bigint) FROM jsonb_array_elements(proposals) r) END);
END $$;
REVOKE ALL ON FUNCTION public.get_waitlist_offer_proposal_internal(bigint,bigint,integer) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_waitlist_offer_proposal(p_form_id bigint)
RETURNS jsonb LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.get_waitlist_offer_proposal_internal(p_form_id,NULL,NULL);
$$;
CREATE OR REPLACE FUNCTION public.enqueue_waitlist_email_internal(p_order bigint,p_offer uuid,p_command uuid,p_delivery jsonb)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE o eshop.orders; occ public.occasions; result jsonb; expiry timestamptz; code text; kind text;
BEGIN
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=p_order; SELECT * INTO STRICT occ FROM public.occasions WHERE id=o.occasion;
 code:=CASE WHEN p_offer IS NULL THEN 'waitlist_confirmation' ELSE 'waitlist_offer' END;
 kind:=code;
 IF p_delivery->>'recipient' IS DISTINCT FROM o.data->>'email' OR p_delivery->>'templateCode' IS DISTINCT FROM code
 OR p_delivery->'sealed' IS NULL OR p_delivery->>'tokenHash' !~ '^[0-9a-f]{64}$'
 OR p_delivery->>'contentHash' !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Invalid waitlist delivery binding'; END IF;
 SELECT expires_at INTO expiry FROM eshop.waitlist_offers WHERE id=p_offer AND order_id=p_order;
 INSERT INTO eshop.waitlist_capabilities(token_hash,organization_id,form_id,order_id,offer_id,kind,expires_at)
 VALUES(p_delivery->>'tokenHash',occ.organization,o.form,o.id,p_offer,CASE WHEN p_offer IS NULL THEN 'manage' ELSE 'offer' END,expiry);
 IF p_offer IS NULL AND p_delivery ? 'overview' THEN
  PERFORM public.issue_order_overview_internal(o.id,p_delivery->'overview',p_command);
 END IF;
 result:=public.enqueue_email(kind,jsonb_build_object('organization',occ.organization,'occasion',occ.id,'unit',occ.unit),o.data->>'email',
 jsonb_build_object('order_id',o.id,'offer_id',p_offer,'command_id',p_command,'content_hash',p_delivery->>'contentHash','waitlistEnvelope',p_delivery->'sealed'),
 p_command::text||':'||o.id::text,code,now(),expiry,o.id,NULL);
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.expire_waitlist_form_internal(bigint,timestamptz,integer),public.enqueue_waitlist_email_internal(bigint,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.get_waitlist_offer_proposal(bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_waitlist_offer_proposal(bigint) TO authenticated;


-- Source: database/functions/eshop_waitlist/email_context.sql
CREATE OR REPLACE FUNCTION public.get_waitlist_email_context_v1(p_operation text,p_payload jsonb,p_actor uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE fid bigint; f public.forms; occ public.occasions; contexts jsonb; r jsonb; o eshop.orders;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_operation='register' THEN SELECT id INTO fid FROM public.forms WHERE key=(p_payload->>'form')::uuid;
 ELSIF p_operation='send' THEN fid:=(p_payload->>'formId')::bigint;
 ELSE RAISE EXCEPTION 'Invalid email context operation'; END IF;
 SELECT * INTO STRICT f FROM public.forms WHERE id=fid; SELECT * INTO STRICT occ FROM public.occasions WHERE id=f.occasion;
 IF p_operation='send' AND NOT public.can_write_orders_as_actor_internal(p_actor,occ.id) THEN
  RAISE insufficient_privilege USING MESSAGE='Order editor required'; END IF;
 contexts:='[]';
 IF p_operation='register' THEN contexts:=jsonb_build_array(jsonb_build_object('recipient',p_payload->>'email','organization',occ.organization,
  'occasion',occ.id,'unit',occ.unit,'occasionTitle',occ.title,'participantCount',jsonb_array_length(p_payload->'tickets'),'formLink',f.link));
 ELSE
  FOR r IN SELECT * FROM jsonb_array_elements(p_payload->'recipients') LOOP
   SELECT * INTO STRICT o FROM eshop.orders WHERE id=(r->>'orderId')::bigint AND form=fid;
   contexts:=contexts||jsonb_build_array(jsonb_build_object('orderId',o.id,'recipient',o.data->>'email','organization',occ.organization,
   'occasion',occ.id,'unit',occ.unit,'occasionTitle',occ.title,'orderSymbol',o.order_symbol,
   'participantCount',(SELECT count(*) FROM public.get_order_tickets_internal(o.id)),
   'offeredCount',(r->>'count')::integer,'formLink',f.link,'expiresAt',p_payload->>'expiresAt'));
  END LOOP;
 END IF;
 RETURN contexts;
END $$;
REVOKE ALL ON FUNCTION public.get_waitlist_email_context_v1(text,jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_waitlist_email_context_v1(text,jsonb,uuid) TO service_role;


-- Source: database/functions/eshop_forms/admin_form_waitlist.sql
-- Scope/delegation adapters only. Existing waitlist command and encrypted email
-- delivery pipeline own mutation, receipt, ticket identity and notifications.
CREATE OR REPLACE FUNCTION public.get_form_waitlist_context(p_occasion bigint,p_organization bigint,p_unit bigint,p_form bigint,
 p_operation text,p_payload jsonb DEFAULT '{}')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb; offer uuid; oid bigint;
BEGIN
 IF p_operation IS NULL OR p_operation NOT IN('proposal','detail','send','cancel','withdraw','accept','decline') OR jsonb_typeof(p_payload)<>'object' THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid waitlist intent'; END IF;
 PERFORM public.check_form_order_scope_internal(p_occasion,p_organization,p_unit,p_form,p_operation<>'detail');
 IF p_operation IN('detail','withdraw') THEN
  oid:=(p_payload->>'orderId')::bigint;
  IF NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=oid AND form=p_form AND occasion=p_occasion) THEN
   RAISE insufficient_privilege USING MESSAGE='foreign waiting order'; END IF;
 ELSIF p_operation IN('cancel','accept','decline') THEN
  offer:=(p_payload->>'offerId')::uuid;
  IF NOT EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE id=offer AND form_id=p_form) THEN
   RAISE insufficient_privilege USING MESSAGE='foreign offer'; END IF;
 ELSIF p_operation='send' THEN
  IF (p_payload->>'formId')::bigint IS DISTINCT FROM p_form OR
   jsonb_typeof(p_payload->'recipients') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'recipients') NOT BETWEEN 1 AND 100 OR
   EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'recipients') r WHERE NOT EXISTS(
     SELECT 1 FROM eshop.orders o WHERE o.id=(r->>'orderId')::bigint AND o.form=p_form AND o.occasion=p_occasion)) THEN
   RAISE insufficient_privilege USING MESSAGE='foreign waitlist recipients'; END IF;
 END IF;
 IF p_operation='proposal' THEN
  IF coalesce((p_payload->>'limit')::int,50) NOT BETWEEN 1 AND 100 THEN RAISE invalid_parameter_value USING MESSAGE='invalid waitlist page'; END IF;
  result:=public.get_waitlist_offer_proposal_internal(p_form,(p_payload->>'after')::bigint,coalesce((p_payload->>'limit')::int,50));
 ELSIF p_operation='detail' THEN result:=public.get_waitlist_order_detail(oid);
 ELSE result:='{}'; END IF;
 IF octet_length(result::text)>1048576 THEN RAISE program_limit_exceeded USING MESSAGE='waitlist detail too large'; END IF;
 RETURN jsonb_build_object('occasionId',p_occasion,'formId',p_form,'result',result);
END $$;
REVOKE ALL ON FUNCTION public.get_form_waitlist_context(bigint,bigint,bigint,bigint,text,jsonb) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.get_form_waitlist_context(bigint,bigint,bigint,bigint,text,jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.execute_admin_waitlist_command_client_sync_v1(p_administration jsonb,p_operation text,p_payload jsonb,
 p_command_id uuid,p_client_id uuid,p_actor uuid,p_deliveries jsonb DEFAULT '[]')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE previous_sub text:=current_setting('request.jwt.claim.sub',true); result jsonb; occ bigint; fid bigint;
 prior jsonb; preview jsonb; quote jsonb; receipt_status text;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_actor IS NULL OR p_operation NOT IN('send','cancel','withdraw','accept','decline') THEN RAISE insufficient_privilege USING MESSAGE='administrative waitlist actor required'; END IF;
 occ:=(p_administration->>'occasionId')::bigint;fid:=(p_administration->>'formId')::bigint;
 PERFORM set_config('request.jwt.claim.sub',p_actor::text,true);
 PERFORM public.check_form_order_scope_internal(occ,(p_administration->>'organizationId')::bigint,(p_administration->>'unitId')::bigint,fid);
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 PERFORM 1 FROM public.forms WHERE id=fid FOR UPDATE;
 PERFORM public.get_form_waitlist_context(occ,(p_administration->>'organizationId')::bigint,(p_administration->>'unitId')::bigint,fid,p_operation,p_payload);
 IF p_operation='accept' THEN
  p_payload:=p_payload||jsonb_build_object('orderDetails',public.form_order_input_internal(fid,p_payload->'orderDetails'));
  IF p_payload->>'approvalHash' IS NULL OR p_payload->>'approvalHash' !~ '^[a-f0-9]{64}$' THEN
   RAISE invalid_parameter_value USING MESSAGE='waiting acceptance approval required'; END IF;
  SELECT response,status INTO prior,receipt_status FROM public.client_mutation_receipts WHERE command_id=p_command_id
   AND actor_id=p_actor AND occasion=occ AND command_name='inventory.waitlist.accept';
  IF receipt_status='expired' THEN
   PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true);
   RETURN jsonb_build_object('code',410,'errorCode','COMMAND_EXPIRED_DO_NOT_REPLAY'); END IF;
  IF prior IS NULL THEN
   preview:=public.preview_admin_waitlist_acceptance(p_administration,p_payload,p_actor);
   IF (preview->>'code')::int<>200 OR preview->>'confirmationHash' IS DISTINCT FROM p_payload->>'approvalHash' THEN
    PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true);
    RETURN jsonb_build_object('code',409,'errorCode','ORDER_CHANGED_REPREVIEW_REQUIRED'); END IF;
   quote:=preview->'quote';
  ELSE quote:=prior#>'{data,adminQuote}'; END IF;
  p_payload:=p_payload||jsonb_build_object('administrativeApproval',jsonb_build_object('quote',quote,
   'scope',jsonb_build_object('occasionId',occ,'formId',fid,'actorId',p_actor)));
 END IF;
 result:=public.execute_waitlist_command_client_sync_v1(p_operation,p_payload,p_command_id,p_client_id,p_actor,p_deliveries);
 IF p_operation='accept' AND (result->>'code')::int=200 THEN
  IF prior IS NULL AND public.form_order_quote_internal((result#>>'{data,order,id}')::bigint) IS DISTINCT FROM quote THEN
   RAISE serialization_failure USING MESSAGE='waiting acceptance quote changed'; END IF;
  result:=result||jsonb_build_object('data',(result->'data')||jsonb_build_object('quote',result#>'{data,adminQuote}'));
 END IF;

 PERFORM public.get_form_waitlist_context(occ,(p_administration->>'organizationId')::bigint,(p_administration->>'unitId')::bigint,fid,p_operation,p_payload);
 PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true);
 RETURN result;
EXCEPTION WHEN OTHERS THEN
 PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true); RAISE;
END $$;
REVOKE ALL ON FUNCTION public.execute_admin_waitlist_command_client_sync_v1(jsonb,text,jsonb,uuid,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.execute_admin_waitlist_command_client_sync_v1(jsonb,text,jsonb,uuid,uuid,uuid,jsonb) TO service_role;
